import React, { useState } from "react";

export default function ApplyForm() {
  const [formData, setFormData] = useState({
    name: "",
    operatingRegion: "",
    cuisineType: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:8080/addVendor", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error("Failed to submit");
      }

      alert("Vendor added successfully!");
      setFormData({ name: "", operatingRegion: "", cuisineType: "" });
    } catch (error) {
      console.error("Error submitting form", error);
      alert("Error adding vendor. Please try again.");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="p-4 max-w-md mx-auto space-y-4">
      <input
        name="name"
        value={formData.name}
        onChange={handleChange}
        placeholder="Vendor Name"
        className="border p-2 w-full"
        required
      />
      <input
        name="operatingRegion"
        value={formData.operatingRegion}
        onChange={handleChange}
        placeholder="Operating Region"
        className="border p-2 w-full"
        required
      />
      <input
        name="cuisineType"
        value={formData.cuisineType}
        onChange={handleChange}
        placeholder="Cuisine Type"
        className="border p-2 w-full"
        required
      />
      <button type="submit" className="bg-blue-500 text-white p-2 rounded">
        Submit
      </button>
    </form>
  );
}
